cat << 'EOF' > test-a11y.js
const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();

  // Use file:// protocol with absolute path
  const filePath = 'file://' + path.join(process.cwd(), 'index.html');
  await page.goto(filePath);

  // Wait for our script to run (it uses DOMContentLoaded)
  await page.waitForLoadState('networkidle');

  // Inject axe-core
  const axeSource = fs.readFileSync(require.resolve('axe-core/axe.min.js'), 'utf8');
  await page.evaluate(axeSource);

  // Run axe
  const results = await page.evaluate(async () => {
    return await window.axe.run();
  });

  const wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
  const bp = results.violations.filter(v => v.tags.includes('best-practice'));

  console.log(JSON.stringify({
    wcag: wcag.map(v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target) })),
    bp: bp.map(v => ({ id: v.id, targets: v.nodes.map(n => n.target) }))
  }, null, 2));

  await browser.close();
  process.exit(wcag.length > 0 ? 1 : 0);
})();
EOF", 'description': 'Create a11y test script'}, intention_summary='Create a11y test script', mcp_server_name=None, tool_title=None, type=<AssistantMessageToolRequestType.FUNCTION: 'function'>)

