 <!DOCTYPE html>
 <html lang="en">
 <head>
     <meta charset="UTF-8">
     <meta name="viewport" content="width=device-width, initial-scale=1.0">
     <title>Cat FAQ - All About Our Feline Friends</title>
     <style>
         :root {
             --primary-color: #2563eb;
             --text-color: #1f2937;
             --text-light: #6b7280;
             --bg-color: #f9fafb;
             --card-bg: #ffffff;
             --border-color: #e5e7eb;
             --focus-ring: #bfdbfe;
         }

         body {
             font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
             line-height: 1.5;
             color: var(--text-color);
             background-color: var(--bg-color);
             margin: 0;
             padding: 2rem 1rem;
         }

         header {
             max-width: 600px;
             margin: 0 auto 3rem;
             text-align: center;
         }

         h1 {
             font-size: 2.5rem;
             font-weight: 800;
             margin-bottom: 0.5rem;
             color: var(--text-color);
         }

         header p {
             color: var(--text-light);
             font-size: 1.125rem;
         }

         .faq-container {
             max-width: 600px;
             margin: 0 auto;
         }

         .example {
             background-color: var(--card-bg);
             border: 1px solid var(--border-color);
             border-radius: 0.75rem;
             margin-bottom: 1rem;
             overflow: hidden;
             transition: box-shadow 0.2s ease;
         }

         .example:hover {
             box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
         }

         .example h2 {
             margin: 0;
             font-size: 1rem;
         }

         .faq-trigger {
             width: 100%;
             text-align: left;
             padding: 1.25rem 1.5rem;
             background: none;
             border: none;
             font-family: inherit;
             font-size: 1.125rem;
             font-weight: 600;
             color: var(--text-color);
             cursor: pointer;
             display: flex;
             justify-content: space-between;
             align-items: center;
             transition: background-color 0.2s ease;
         }

         .faq-trigger:hover {
             background-color: #f3f4f6;
         }

         .faq-trigger:focus {
             outline: 2px solid var(--primary-color);
             outline-offset: -2px;
         }

         .faq-trigger::after {
             content: "";
             display: inline-block;
             width: 0.5rem;
             height: 0.5rem;
             border-right: 2px solid currentColor;
             border-bottom: 2px solid currentColor;
             transform: rotate(45deg);
             transition: transform 0.2s ease;
             margin-left: 1rem;
         }

         .faq-trigger[aria-expanded="true"]::after {
             transform: rotate(-135deg);
         }

         .details {
             padding: 0 1.5rem 1.5rem;
             color: var(--text-light);
         }

         /* Ensure content is hidden when script applies the 'hidden' attribute */
         [hidden] {
             display: none !important;
         }

         footer {
             max-width: 600px;
             margin: 4rem auto 0;
             text-align: center;
             color: var(--text-light);
             font-size: 0.875rem;
